import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    n = int(next(iterator))
    m = int(next(iterator))

    potentials = []
    for _ in range(n):
        potentials.append(int(next(iterator)))

    clubs = []
    for _ in range(n):
        clubs.append(int(next(iterator)))

    d = int(next(iterator))

    leaving_students = []
    for _ in range(d):
        leaving_students.append(int(next(iterator)))

    removed = [False] * (n + 1)
    for k in leaving_students:
        removed[k] = True

    club_members = defaultdict(list)
    for i in range(1, n + 1):
        if not removed[i]:
            club = clubs[i - 1]
            pot = potentials[i - 1]
            club_members[club].append((pot, i))

    def get_max_mex():
        match = {}

        current_mex = 0
        while True:
            found = False
            for club_idx in range(1, m + 1):
                if club_idx in match:
                    continue
                for pot, student_id in club_members[club_idx]:
                    if pot == current_mex:
                        match[club_idx] = student_id
                        found = True
                        break
                if found:
                    break

            if not found:
                break
            current_mex += 1

        return current_mex

    results = []
    for k in leaving_students:
        removed[k] = True
        club_idx = clubs[k - 1]
        pot_val = potentials[k - 1]

        if club_idx in club_members:
            club_members[club_idx] = [(p, sid) for p, sid in club_members[club_idx] if sid != k]
            if not club_members[club_idx]:
                del club_members[club_idx]

        results.append(get_max_mex())

    for res in results:
        print(res)

solve()
